package com.unofficial.southparktv;

import org.json.JSONException;
import org.json.JSONObject;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.*;

public class CatalogTest {
    // Reduced examples observed on the official Season 12 page, not generated by the parser.
    private static final String EPISODE = """
        {"entityType":"episode","id":"68c79aa4-ecfd-11e0-aca6-0026b9414f30",
         "url":"/episodes/4r4367/south-park-major-boobage-season-12-ep-3",
         "media":{"duration":"22:00","lockedLabel":null,"image":{"url":"https://images.paramount.tech/uri/example"}},
         "meta":{"subHeader":"Major Boobage","description":"A homage to Heavy Metal.","header":{"title":{"text":"S12 • E3"}}}}
        """;

    @Test public void readsJsonAssignmentWithoutExecutingJavascript() throws Exception {
        JSONObject page = Catalog.pageData("<script>window.__DATA__ = {\"title\":\"a }; quoted value\"}; window.executableCode();</script>");
        assertEquals("a }; quoted value", page.getString("title"));
    }

    @Test(expected = JSONException.class) public void rejectsMissingWebsiteData() throws Exception {
        Catalog.pageData("<html>Service unavailable</html>");
    }

    @Test public void discoversAndSortsSeasonsIncludingSelectedNullUrl() throws Exception {
        JSONObject page = new JSONObject("""
            {"children":[{"props":{"items":[
              {"label":"Season 29","seasonNumber":29,"url":"/seasons/south-park/u4jry6/season-29"},
              {"label":"Season 12","seasonNumber":12,"url":null},
              {"label":"Season 1","seasonNumber":1,"url":"/seasons/south-park/yjy8n9/season-1"}
            ]}}]}
            """);
        List<Catalog.Season> seasons = Catalog.seasons(page, "/seasons/south-park/gfstdd/season-12");
        assertEquals(3, seasons.size());
        assertEquals(1, seasons.get(0).number());
        assertEquals(12, seasons.get(1).number());
        assertEquals("/seasons/south-park/gfstdd/season-12", seasons.get(1).path());
        assertEquals(29, seasons.get(2).number());
    }

    @Test public void parsesCardsAndRetainsNextPage() throws Exception {
        JSONObject page = new JSONObject("{\"children\":[{\"props\":{\"isEpisodes\":true,\"items\":[" + EPISODE + "],"
                + "\"loadMore\":{\"url\":\"/api/context/season/episode/2/10\"}}}]}");
        Catalog.SeasonPage result = Catalog.seasonPage(page);
        assertEquals("/api/context/season/episode/2/10", result.nextPage());
        assertEquals(1, result.episodes().size());
        Catalog.Episode episode = result.episodes().get(0);
        assertEquals("Major Boobage", episode.title());
        assertEquals("S12 • E3", episode.label());
        assertEquals("22:00", episode.duration());
        assertFalse(episode.locked());
    }

    @Test public void excludesClipsButKeepsLockedEpisodeVisible() throws Exception {
        JSONObject locked = new JSONObject(EPISODE);
        locked.getJSONObject("media").put("lockedLabel", "Subscription required");
        JSONObject feed = new JSONObject("{\"items\":[{\"entityType\":\"video\"}," + locked + "]}");
        List<Catalog.Episode> episodes = Catalog.episodes(feed);
        assertEquals(1, episodes.size());
        assertTrue(episodes.get(0).locked());
    }

    @Test public void clipOnlySeasonIsEmptyNotAnError() throws Exception {
        JSONObject page = new JSONObject("{\"props\":{\"type\":\"video-guide\",\"isEpisodes\":false,\"items\":[{\"entityType\":\"showvideo\"}],\"filters\":{\"items\":[{\"url\":\"/api/context/season/video/1/12\"}]}}}");
        Catalog.SeasonPage result = Catalog.seasonPage(page);
        assertTrue(result.episodes().isEmpty());
        assertEquals("", result.nextPage());
    }

    @Test public void videoGuideCanLinkToFullEpisodesWithoutEmbeddingThem() throws Exception {
        JSONObject page = new JSONObject("{\"props\":{\"isEpisodes\":false,\"items\":[],\"filters\":{\"items\":[{\"url\":\"/api/context/season/episode/1/10\"}]}}}");
        assertEquals("/api/context/season/episode/1/10", Catalog.seasonPage(page).nextPage());
    }

    @Test public void findsPlaybackDetailAndPreservesAuthenticationRequirement() throws Exception {
        JSONObject page = new JSONObject("{\"children\":[{\"props\":{\"videoDetail\":{\"authRequired\":true,\"videoServiceUrl\":\"https://topaz.paramount.tech/topaz/api/example/mica.json\"}}}]}");
        assertTrue(Catalog.videoDetail(page).getBoolean("authRequired"));
    }

    @Test public void acceptsOnlyOfficialHttpsPageUrls() {
        assertEquals("https://www.southparkstudios.com/episodes/example", Catalog.officialPage("/episodes/example"));
        for (String unsafe : new String[]{"https://evil.example/episodes/a", "//evil.example/a", "http://www.southparkstudios.com/", "https://www.southparkstudios.com@evil.example/", "https://www.southparkstudios.com:8443/"}) {
            assertThrows(IllegalArgumentException.class, () -> Catalog.officialPage(unsafe));
        }
    }
}
